import numpy as np
import pandas as pd


TARGET_COLUMN = 'target'


class DecisionTree:
    def __init__(self, max_depth=8, min_samples_leaf=10):
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.tree = None

    def _gini(self, y):
        m = len(y)
        if m == 0:
            return 0.0
        p0 = np.mean(y == 0)
        p1 = np.mean(y == 1)
        return 1.0 - p0 * p0 - p1 * p1

    def _best_split(self, X, y):
        n_samples, n_features = X.shape
        best_gain = -1
        best_feat = None
        best_thresh = None
        parent_gini = self._gini(y)

        candidates = np.random.choice(n_features, min(n_features, max(1, int(np.sqrt(n_features)) * 2)), replace=False)
        for feat in candidates:
            thresholds = np.quantile(X[:, feat], [0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9])
            for thresh in thresholds:
                left = y[X[:, feat] <= thresh]
                right = y[X[:, feat] > thresh]
                if len(left) < self.min_samples_leaf or len(right) < self.min_samples_leaf:
                    continue
                gain = parent_gini - (len(left) / n_samples * self._gini(left) +
                                     len(right) / n_samples * self._gini(right))
                if gain > best_gain:
                    best_gain = gain
                    best_feat = feat
                    best_thresh = thresh
        return best_feat, best_thresh, best_gain

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < self.min_samples_leaf * 2:
            return {'leaf': 1 if np.mean(y) > 0.5 else 0}

        n0, n1 = np.sum(y == 0), np.sum(y == 1)
        if n0 == 0 or n1 == 0:
            return {'leaf': 1 if n1 > n0 else 0}

        feat, thresh, gain = self._best_split(X, y)
        if feat is None or gain <= 0:
            return {'leaf': 1 if n1 > n0 else 0}

        left_mask = X[:, feat] <= thresh
        return {'feat': feat, 'thresh': thresh,
                'left': self._build(X[left_mask], y[left_mask], depth + 1),
                'right': self._build(X[~left_mask], y[~left_mask], depth + 1)}

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)

    def _predict_one(self, row):
        node = self.tree
        while isinstance(node, dict):
            node = node['left'] if row[node['feat']] <= node['thresh'] else node['right']
        return node

    def predict(self, X):
        return np.array([self._predict_one(row) for row in X])


class RandomForest:
    def __init__(self, n_trees=200, max_depth=8, min_samples_leaf=10):
        self.n_trees = n_trees
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.trees = []

    def fit(self, X, y):
        n = len(X)
        for i in range(self.n_trees):
            idx = np.random.choice(n, n, replace=True)
            tree = DecisionTree(self.max_depth, self.min_samples_leaf)
            tree.fit(X[idx], y[idx])
            self.trees.append(tree)

    def predict_proba(self, X):
        preds = np.array([tree.predict(X) for tree in self.trees])
        return preds.mean(axis=0)

    def predict(self, X):
        return (self.predict_proba(X) >= 0.5).astype(np.int64)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c.startswith('x')]
    X = train[feature_cols].values.astype(np.float64)
    y = train[TARGET_COLUMN].values.astype(np.int64)
    X_test = test[feature_cols].values.astype(np.float64)

    rf = RandomForest(n_trees=300, max_depth=8, min_samples_leaf=10)
    rf.fit(X, y)
    probs = rf.predict_proba(X_test)
    preds = (probs >= 0.5).astype(np.int64)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)

